// n8n Code node: Run Once for All Items
// Replaces the entire body of "De-duplicate Job Posts".
// Deliberately avoids the global URL constructor, which may be unavailable in n8n's Code sandbox.

const items = $input.all();
const byId = new Map();
const invalidJobs = [];
let duplicateCount = 0;

function text(value) {
  return value == null ? '' : String(value).trim();
}

function summarizeSource(job, reason) {
  return {
    title: text(job?.title) || 'Unknown LinkedIn job',
    job_url: text(job?.link || job?.job_url),
    reason,
  };
}

function parseLinkedInUrl(rawUrl) {
  // LinkedIn feed URLs shouldn't contain unescaped spaces or control characters.
  if (/[\u0000-\u0020\u007f]/.test(rawUrl)) {
    throw new Error('LinkedIn job URL contains whitespace or control characters.');
  }

  // Parse only the absolute HTTPS structure needed by this workflow.
  const match = rawUrl.match(
    /^https:\/\/([^/?#]+)(\/[^?#]*)?(?:\?([^#]*))?(?:#.*)?$/i,
  );
  if (!match) {
    throw new Error('LinkedIn job URL must be an absolute HTTPS URL.');
  }

  const authority = match[1].toLowerCase();
  if (authority.includes('@')) {
    throw new Error('LinkedIn job URL must not contain user information.');
  }

  // Port 443 is equivalent to normal HTTPS. Other explicit ports are rejected by
  // the hostname allowlist below.
  const host = authority.replace(/:443$/, '');
  if (host !== 'linkedin.com' && !host.endsWith('.linkedin.com')) {
    throw new Error('Job URL is not on linkedin.com.');
  }

  return {
    pathname: match[2] || '/',
    query: match[3] || '',
  };
}

function canonicalLinkedInJob(job) {
  const directId = text(job?.job_id);
  const rawUrl = text(job?.link || job?.job_url);
  if (!rawUrl) throw new Error('Missing LinkedIn job URL.');

  const parsed = parseLinkedInUrl(rawUrl);
  const candidates = [];

  if (directId) {
    if (!/^\d{6,20}$/.test(directId)) {
      throw new Error('Existing job_id is not a valid numeric LinkedIn job ID.');
    }
    candidates.push(directId);
  }

  // LinkedIn search/collection URLs can carry the selected job in a query parameter.
  for (const key of ['currentJobId', 'jobId']) {
    const queryMatch = parsed.query.match(
      new RegExp(`(?:^|&)${key}=(\\d{6,20})(?:&|$)`),
    );
    if (queryMatch) candidates.push(queryMatch[1]);
  }

  // Supports both:
  // /jobs/view/security-engineer-at-company-4468699157
  // /jobs/view/4468699157
  const pathMatch = parsed.pathname.match(
    /\/jobs\/view\/(?:[^/?#]*-)?(\d{6,20})\/?$/i,
  );
  if (pathMatch) candidates.push(pathMatch[1]);

  const unique = [...new Set(candidates)];
  if (unique.length === 0) {
    throw new Error('Unable to extract a numeric LinkedIn job ID.');
  }
  if (unique.length > 1) {
    throw new Error('Conflicting LinkedIn job IDs were found in the record.');
  }

  const jobId = unique[0];
  const canonicalUrl = `https://www.linkedin.com/jobs/view/${jobId}`;

  return {
    ...job,
    item_type: 'job',
    job_id: jobId,
    source_link: rawUrl,
    link: canonicalUrl,
    job_url: canonicalUrl,
  };
}

for (const item of items) {
  try {
    const normalized = canonicalLinkedInJob(item.json || {});
    if (byId.has(normalized.job_id)) {
      duplicateCount += 1;
      continue;
    }
    byId.set(normalized.job_id, normalized);
  } catch (error) {
    invalidJobs.push(
      summarizeSource(item.json || {}, String(error?.message || error)),
    );
  }
}

const runIngestMeta = {
  source_execution_id: String($execution.id),
  feed_count: items.length,
  canonical_distinct_count: byId.size,
  duplicate_count: duplicateCount,
  invalid_count: invalidJobs.length,
  invalid_jobs: invalidJobs.slice(0, 20),
  invalid_jobs_omitted: Math.max(0, invalidJobs.length - 20),
};

const normalizedItems = [...byId.values()].map((job) => ({
  json: { ...job, run_ingest_meta: runIngestMeta },
}));

if (normalizedItems.length > 0) return normalizedItems;

return [
  {
    json: {
      item_type: 'run_control',
      run_control: 'no_valid_jobs',
      run_ingest_meta: runIngestMeta,
    },
  },
];

const existingJobIds = new Set(
  $input.all()
    .map((item) => String(item.json?.job_id || '').trim())
    .filter((value) => /^\d{6,20}$/.test(value))
);

const normalizedItems = $('De-duplicate Job Posts').all();
const candidates = normalizedItems.filter((item) => item.json?.item_type === 'job');
const newJobs = candidates.filter((item) => !existingJobIds.has(String(item.json.job_id)));
const ingestMeta = normalizedItems.find((item) => item.json?.run_ingest_meta)?.json?.run_ingest_meta || {};
const runContext = {
  ...ingestMeta,
  existing_count: Math.max(0, candidates.length - newJobs.length),
  new_count: newJobs.length,
  expected_job_ids: newJobs.map((item) => String(item.json.job_id)),
};

if (newJobs.length > 0) {
  return newJobs.map((item) => ({
    json: {
      ...item.json,
      run_context: runContext,
    },
  }));
}

return [{
  json: {
    item_type: 'run_control',
    run_control: candidates.length === 0 ? 'no_valid_jobs' : 'no_new_jobs',
    report_state: candidates.length === 0 ? 'no_valid_jobs' : 'no_new_jobs',
    source_execution_id: String($execution.id),
    run_context: runContext,
    jobs: [],
    failed_jobs: [],
    counts: {
      feed: Number(runContext.feed_count || 0),
      distinct: Number(runContext.canonical_distinct_count || 0),
      duplicates: Number(runContext.duplicate_count || 0),
      invalid: Number(runContext.invalid_count || 0),
      existing: Number(runContext.existing_count || 0),
      new: 0,
      selected: 0,
      rejected: 0,
      failed: 0,
      emailed: 0,
      omitted_by_limit: 0,
      database_missing: 0,
    },
    ingest_failures: Array.isArray(runContext.invalid_jobs) ? runContext.invalid_jobs : [],
  },
}];

