// Complete replacement code for n8n node: Generate Jobs Email HTML

const report = $input.first().json || {};
const jobs = Array.isArray(report.jobs) ? report.jobs : [];
if (jobs.length === 0) throw new Error('Refusing to generate a selected-jobs email with zero jobs.');
const reportLimit = Number(report.report_limit);
if (!Number.isInteger(reportLimit) || reportLimit < 1) {
  throw new Error('Selected-jobs report has an invalid report_limit.');
}
if (jobs.length > reportLimit) {
  throw new Error(`Selected-jobs report contains ${jobs.length} jobs for a limit of ${reportLimit}.`);
}

const required = ['job_id', 'position', 'company_name', 'joburl'];
for (const [index, job] of jobs.entries()) {
  const missing = required.filter((key) => job?.[key] == null || String(job[key]).trim() === '');
  if (missing.length) throw new Error(`Job ${index} is missing required fields: ${missing.join(', ')}`);
}

function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
function display(value, fallback = 'Not available') {
  const normalized = String(value ?? '').trim();
  return esc(normalized || fallback);
}
function safeLinkedInUrl(value) {
  const raw = String(value || '').trim();
  if (!raw || /[\u0000-\u0020\u007f]/.test(raw)) return null;
  const match = raw.match(/^https:\/\/([^/?#]+)(\/[^?#]*)?(?:\?[^#]*)?(?:#.*)?$/i);
  if (!match) return null;
  const authority = match[1].toLowerCase();
  if (authority.includes('@')) return null;
  const host = authority.replace(/:443$/, '');
  if (host !== 'linkedin.com' && !host.endsWith('.linkedin.com')) return null;
  return raw;
}
function listHtml(value, fallback) {
  const entries = String(value ?? '')
    .split('[END_OF_BULLET]')
    .map((entry) => entry.trim())
    .filter(Boolean);
  if (entries.length === 0) return `<li>${esc(fallback)}</li>`;
  return entries.map((entry) => `<li>${esc(entry)}</li>`).join('');
}
function dimBadge(value) {
  if (value === null || value === undefined || value === 'null' || value === '') {
    return '<span class="dim-score dim-null" title="Not available">—</span>';
  }
  const number = Number(value);
  if (!Number.isFinite(number)) return '<span class="dim-score dim-null" title="Not available">—</span>';
  const cls = number >= 4 ? 'dim-high' : number >= 3 ? 'dim-mid' : 'dim-low';
  return `<span class="dim-score ${cls}" title="Score ${esc(number)} out of 5">${esc(number)}</span>`;
}

const counts = report.counts || {};
const failures = Array.isArray(report.failed_jobs) ? report.failed_jobs : [];
const visibleFailures = failures.slice(0, 20);
const failureItems = visibleFailures.map((failure) => {
  const url = safeLinkedInUrl(failure.job_url);
  const label = display(failure.title || failure.job_id, 'LinkedIn job');
  const link = url ? `<a href="${esc(url)}">${label}</a>` : label;
  return `<li>${link} — ${display(failure.summary, 'Automated analysis failed after retries.')}</li>`;
}).join('');
const hiddenFailureCount = Math.max(0, failures.length - visibleFailures.length);

const cards = jobs.map((job) => {
  const url = safeLinkedInUrl(job.joburl);
  if (!url) throw new Error(`Job ${job.job_id} has an invalid LinkedIn URL.`);
  return `<article class="card">
    <div class="card-header">
      <h2>${display(job.position)} at ${display(job.company_name)}</h2>
      <a href="${esc(url)}" class="button">View job posting</a>
    </div>
    <div class="job-info">
      <span><strong>Job ID:</strong> ${display(job.job_id)}</span>
      <span><strong>Location:</strong> ${display(job.location)}</span>
      <span><strong>Salary:</strong> ${display(job.salary)}</span>
      <span><strong>Posted:</strong> ${display(job.posted_date)}</span>
    </div>
    <table class="ratings-table">
      <caption>Fit ratings</caption>
      <thead><tr><th scope="col">Overall</th><th scope="col">Preference</th><th scope="col">Skill</th><th scope="col">Explanation</th></tr></thead>
      <tbody><tr><td>${display(job.overall_rating)}</td><td>${display(job.preferences_rating)}</td><td>${display(job.skill_rating)}</td><td>${display(job.evaluation)}</td></tr></tbody>
    </table>
    <table class="dim-table">
      <caption>Dimension ratings</caption>
      <thead><tr><th scope="col">Employee satisfaction</th><th scope="col">Salary</th><th scope="col">Remote flexibility</th><th scope="col">Skills alignment</th><th scope="col">Cultural fit</th></tr></thead>
      <tbody><tr><td>${dimBadge(job.dim_employee_satisfaction)}</td><td>${dimBadge(job.dim_salary_competitiveness)}</td><td>${dimBadge(job.dim_remote_work_flexibility)}</td><td>${dimBadge(job.dim_skills_alignment)}</td><td>${dimBadge(job.dim_cultural_fit)}</td></tr></tbody>
    </table>
    <section><h3>Preference matches</h3><ul>${listHtml(job.preference_matches, 'No preference matches')}</ul></section>
    <section><h3>References</h3><ul>${listHtml(job.preference_references, 'No preference references')}</ul></section>
    <section><h3>Preference misses</h3><ul>${listHtml(job.preference_misses, 'No preference misses')}</ul></section>
    <section><h3>Potential preference matches</h3><ul>${listHtml(job.potential_preference_matches, 'No potential preference matches')}</ul></section>
    <section><h3>Skill matches</h3><ul>${listHtml(job.skill_matches, 'No skill matches')}</ul></section>
    <section><h3>Skill misses</h3><ul>${listHtml(job.skill_misses, 'No skill misses')}</ul></section>
    <section><h3>Transferable skills</h3><ul>${listHtml(job.skill_translations, 'No transferable skills')}</ul></section>
  </article>`;
}).join('');

const omittedNotice = Number(counts.omitted_by_limit || 0) > 0
  ? `<p><strong>${esc(counts.omitted_by_limit)} additional qualifying job(s)</strong> were not included because this report is capped at ${esc(reportLimit)} current-run jobs.</p>`
  : '';
const databaseWarning = Number(counts.database_missing || 0) > 0
  ? `<p><strong>Warning:</strong> ${esc(counts.database_missing)} selected job(s) could not be read back from the database.</p>`
  : '';
const failureSection = failures.length > 0
  ? `<section class="review"><h2>Jobs requiring manual review (${esc(failures.length)})</h2><p>Automated analysis failed after three attempts. These jobs were not scored or selected automatically.</p><ul>${failureItems}</ul>${hiddenFailureCount ? `<p>${esc(hiddenFailureCount)} additional failure(s) are available in the execution record.</p>` : ''}</section>`
  : '';

const html = `<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Current Job Search Report</title>
<style>
body{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:#f4f7fa;color:#111827;line-height:1.6;margin:0;padding:20px}.container{max-width:1100px;margin:0 auto;background:#fff;border-radius:12px;padding:24px}h1{text-align:center;font-size:26px}h2{font-size:19px}h3{font-size:16px}.summary,.review{border:1px solid #94a3b8;border-radius:10px;padding:16px;margin:20px 0}.card{border:2px solid #64748b;border-radius:10px;padding:16px;margin:20px 0;background:#f8fafc}.card-header{display:flex;justify-content:space-between;align-items:center;gap:16px}.button{display:inline-block;padding:10px 14px;min-height:24px;background:#1d4ed8;color:#fff!important;text-decoration:none;border-radius:6px;font-weight:700}.job-info{display:grid;grid-template-columns:1fr 1fr;gap:8px 16px;margin-bottom:16px}table{width:100%;border-collapse:collapse;margin:16px 0}caption{text-align:left;font-weight:700;margin-bottom:6px}th,td{padding:8px;text-align:left;border-bottom:1px solid #cbd5e1}.dim-table th,.dim-table td{text-align:center}.dim-score{display:inline-block;min-width:28px;height:28px;line-height:28px;border-radius:50%;font-weight:700;color:#fff}.dim-high{background:#166534}.dim-mid{background:#92400e}.dim-low{background:#991b1b}.dim-null{background:#475569}a{color:#1d4ed8}ul{padding-left:22px}@media(max-width:650px){body{padding:8px}.container{padding:14px}.card-header{display:block}.button{margin-top:8px}.job-info{grid-template-columns:1fr}th,td{font-size:12px;padding:5px}}
</style></head><body><main class="container"><h1>Current Job Search Report</h1>
<section class="summary"><h2>Run summary</h2><p>${esc(counts.feed || 0)} feed item(s) → ${esc(counts.distinct || 0)} distinct job(s) → ${esc(counts.new || 0)} new job(s) → ${esc(counts.selected || 0)} selected, ${esc(counts.rejected || 0)} rejected, ${esc(counts.failed || 0)} failed.</p>${omittedNotice}${databaseWarning}</section>
${cards}${failureSection}</main></body></html>`;

return [{ json: { ...report, output: html, subject: `Job Search Report — ${jobs.length} current match${jobs.length === 1 ? '' : 'es'}` } }];

const ledger = $('Build Run Ledger').first().json;
const selectedIds = new Set((ledger.selected_job_ids || []).map((value) => String(value)));
const rows = $input.all()
  .map((item) => item.json || {})
  .filter((row) => /^\d{6,20}$/.test(String(row.job_id || '')))
  .filter((row) => selectedIds.has(String(row.job_id)));

const returnedIds = new Set(rows.map((row) => String(row.job_id)));
if (returnedIds.size !== rows.length) {
  throw new Error('Current-run database query returned duplicate job IDs.');
}

const resultLimit = Number(ledger.report_limit);
if (!Number.isInteger(resultLimit) || resultLimit < 1) {
  throw new Error('Build Run Ledger returned an invalid report_limit.');
}
if (rows.length > resultLimit) {
  throw new Error(`Current-run database query returned ${rows.length} rows for a report limit of ${resultLimit}.`);
}
const expectedRowsWithinLimit = Math.min(selectedIds.size, resultLimit);
const databaseMissing = Math.max(0, expectedRowsWithinLimit - rows.length);
const omittedByLimit = Math.max(0, selectedIds.size - resultLimit);
const reportState = rows.length > 0
  ? (databaseMissing > 0 ? 'selected_jobs_with_warnings' : 'selected_jobs')
  : (selectedIds.size > 0 ? 'report_incomplete' : 'no_qualifying_jobs');

return [{
  json: {
    ...ledger,
    report_state: reportState,
    jobs: rows,
    counts: {
      ...(ledger.counts || {}),
      emailed: rows.length,
      omitted_by_limit: omittedByLimit,
      database_missing: databaseMissing,
    },
  },
}];

const envelope = $input.first().json;
const preferences = envelope.results?.preferences;
const skills = envelope.results?.skills;
const overall = envelope.results?.overall;

if (!preferences || !skills || !overall) {
  throw new Error('Missing one or more validated analysis results.');
}

const BASE_WEIGHTS = {
  employee_satisfaction: 0.25,
  salary_competitiveness: 0.25,
  remote_work_flexibility: 0.20,
  skills_alignment: 0.20,
  cultural_fit: 0.10,
};
const DIMENSIONS = Object.keys(BASE_WEIGHTS);
const present = {};
const missing = [];
let overallScore = 0.0;
let normalizedWeights = {};
let note = '';

if (Number(preferences.preferences_rating) === 0) {
  missing.push(...DIMENSIONS);
  note = 'Veto: preference eligibility failed or remains unverified.';
} else {
  for (const dimension of DIMENSIONS) {
    const value = overall[dimension];
    if (typeof value === 'number' && Number.isFinite(value)) {
      present[dimension] = Math.max(1, Math.min(5, value));
    } else {
      missing.push(dimension);
    }
  }

  const included = Object.keys(present);
  if (included.length === 0) {
    note = 'No valid dimension scores provided.';
  } else {
    const rawWeightSum = included.reduce((sum, key) => sum + BASE_WEIGHTS[key], 0);
    normalizedWeights = Object.fromEntries(
      included.map((key) => [key, BASE_WEIGHTS[key] / rawWeightSum])
    );
    const weightedSum = included.reduce(
      (sum, key) => sum + present[key] * normalizedWeights[key],
      0
    );
    overallScore = Math.round(weightedSum * 10) / 10;
    note = missing.length
      ? `Weights renormalized. Excluded: ${missing.join(', ')}`
      : 'All dimensions present. Weights applied: 25/25/20/20/10.';
  }
}

const expectedDetermination = overallScore >= 3.0 ? 'yes' : 'no';
if (overall.determination !== expectedDetermination) {
  throw new Error(`Validated determination ${overall.determination} does not match calculated score ${overallScore}.`);
}

return [{
  json: {
    ...preferences,
    ...skills,
    ...overall,
    overall_score: overallScore,
    weights_used: Object.fromEntries(
      Object.entries(normalizedWeights).map(([key, value]) => [key, Math.round(value * 1000) / 1000])
    ),
    dimensions_included: Object.keys(present),
    dimensions_excluded: missing,
    dimension_values: present,
    note,
    source_job: envelope.job,
    analysis_meta: envelope.analysis_meta
  }
}];

const jobSource = $('Process Job Postings').item.json;
const researchSource = $input.first().json || {};
const jobId = String(jobSource?.job_id || '').trim();

if (!/^\d{6,20}$/.test(jobId)) {
  throw new Error('Expected a canonical numeric LinkedIn job_id before analysis.');
}

const canonicalUrl = `https://www.linkedin.com/jobs/view/${jobId}`;
const research = researchSource.error
  ? { answer: null, results: [], error: String(researchSource.error), raw: researchSource }
  : researchSource;
const job = {
  ...jobSource,
  item_type: 'job',
  job_id: jobId,
  link: canonicalUrl,
  job_url: canonicalUrl,
};
const resume = `[YOUR_RESUME_IN_MARKDOWN]`;

return [{
  json: {
    job,
    research,
    resume,
    results: {},
    analysis_meta: {
      source_workflow: $workflow.name,
      source_execution_id: String($execution.id),
      created_at: new Date().toISOString(),
    },
  },
}];

// Complete replacement code for n8n node: Handle Preference Analysis Failure

const errorItem = $input.first().json || {};
let envelope;
try {
  envelope = $('Build Analysis Envelope').item.json;
} catch (linkError) {
  throw new Error(`Unable to resolve the failing job envelope for preferences analysis: ${String(linkError?.message || linkError)}`);
}
const job = envelope.job || {};
const diagnosticError = String(errorItem.error || errorItem.message || 'Unknown sub-workflow failure');
console.error('Job analysis stage failed after retries', {
  stage: 'preferences', attempts: 3, execution_id: String($execution.id),
  job_id: String(job.job_id || ''), error: diagnosticError,
});
return [{
  json: {
    outcome_status: 'failed',
    source_execution_id: String(envelope.analysis_meta?.source_execution_id || $execution.id),
    job_id: String(job.job_id || ''),
    title: String(job.title || 'LinkedIn job'),
    company_name: String(job.company_name || job.company || ''),
    job_url: String(job.source_link || job.link || job.job_url || ''),
    failure_stage: 'preferences',
    failure_summary: 'Automated preferences analysis failed after 3 attempts.',
    diagnostic_error: diagnosticError,
    run_context: job.run_context || {},
  },
}];

// Complete replacement code for n8n node: Handle Skill Analysis Failure

const errorItem = $input.first().json || {};
let envelope;
try {
  envelope = $('Execute Preference Analysis').item.json;
} catch (linkError) {
  throw new Error(`Unable to resolve the failing job envelope for skills analysis: ${String(linkError?.message || linkError)}`);
}
const job = envelope.job || {};
const diagnosticError = String(errorItem.error || errorItem.message || 'Unknown sub-workflow failure');
console.error('Job analysis stage failed after retries', {
  stage: 'skills', attempts: 3, execution_id: String($execution.id),
  job_id: String(job.job_id || ''), error: diagnosticError,
});
return [{
  json: {
    outcome_status: 'failed',
    source_execution_id: String(envelope.analysis_meta?.source_execution_id || $execution.id),
    job_id: String(job.job_id || ''),
    title: String(job.title || 'LinkedIn job'),
    company_name: String(job.company_name || job.company || ''),
    job_url: String(job.source_link || job.link || job.job_url || ''),
    failure_stage: 'skills',
    failure_summary: 'Automated skills analysis failed after 3 attempts.',
    diagnostic_error: diagnosticError,
    run_context: job.run_context || {},
  },
}];

// Complete replacement code for n8n node: Handle Overall Analysis Failure

const errorItem = $input.first().json || {};
let envelope;
try {
  envelope = $('Execute Skill Analysis').item.json;
} catch (linkError) {
  throw new Error(`Unable to resolve the failing job envelope for overall analysis: ${String(linkError?.message || linkError)}`);
}
const job = envelope.job || {};
const diagnosticError = String(errorItem.error || errorItem.message || 'Unknown sub-workflow failure');
console.error('Job analysis stage failed after retries', {
  stage: 'overall', attempts: 3, execution_id: String($execution.id),
  job_id: String(job.job_id || ''), error: diagnosticError,
});
return [{
  json: {
    outcome_status: 'failed',
    source_execution_id: String(envelope.analysis_meta?.source_execution_id || $execution.id),
    job_id: String(job.job_id || ''),
    title: String(job.title || 'LinkedIn job'),
    company_name: String(job.company_name || job.company || ''),
    job_url: String(job.source_link || job.link || job.job_url || ''),
    failure_stage: 'overall',
    failure_summary: 'Automated overall analysis failed after 3 attempts.',
    diagnostic_error: diagnosticError,
    run_context: job.run_context || {},
  },
}];

const row = $input.first().json || {};
const calculated = $('Calculate Job Fit Score').item.json;
const job = calculated.source_job || {};
return [{
  json: {
